<div class="narrow"><h1>اعلان‌های حساب</h1><?php if(!$rows): ?><div class="empty card section">اعلانی برای حساب شما ثبت نشده است.</div><?php endif; ?><?php foreach($rows as $row): ?><article class="card section"><h2><?= $this->h($row['title']) ?></h2><p><?= $this->h($row['body']) ?></p><p><time data-timestamp="<?= (int)$row['created_at'] ?>"><?= $this->h(gmdate('Y-m-d H:i',(int)$row['created_at'])) ?></time> · <?= $this->h($row['category']) ?></p><?php if($row['destination']): ?><a class="secondary" href="<?= $this->h($this->url($row['destination'])) ?>">مشاهده موضوع اعلان</a><?php endif; ?><?php if(!$row['read_at']): ?><?= $this->start('/notifications/read') ?><input type="hidden" name="id" value="<?= $this->h($row['id']) ?>"><button class="secondary">خواندم</button></form><?php else: ?><span class="tag">خوانده‌شده</span><?php endif; ?></article><?php endforeach; ?></div>
